def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if not isinstance(value, timedelta):
        raise ValueError("Expected a timedelta object")
    return {
        'days': value.days,
        'seconds': value.seconds,
        'microseconds': value.microseconds
    }

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    if not isinstance(value, time):
        raise TypeError("value must be an instance of datetime.time")
    return value.isoformat()

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if not isinstance(value, Point):
        raise TypeError("Expected a Point instance, got {}".format(type(value).__name__))
    return {
        "lat": value.lat,
        "lon": value.lon,
        "time": value.time.isoformat() if hasattr(value, 'time') and value.time else None
    }

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        if not hasattr(self, '_record') or not isinstance(self._record, dict):
            raise ValueError("Invalid record format")
        return list(self._record.keys())
    except Exception as e:
        raise RuntimeError(f"Error retrieving keys: {e}")

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("Protocol version must be provided as a tuple")

    # Example dictionary of protocol handlers
    protocol_handlers = {
        (3, 5): cls.Handler35,
        (4, 0): cls.Handler40,
        (4, 1): cls.Handler41,
    }

    if protocol_version is None:
        return protocol_handlers
    else:
        return {protocol_version: protocol_handlers[protocol_version]} if protocol_version in protocol_handlers else {}

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._data.index(key)
    except ValueError:
        raise KeyError(f'Key {key} not found in the data')

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not keys:
        return list(self._record.values())

    result = []
    for key in keys:
        try:
            if isinstance(key, int):
                result.append(list(self._record.values())[key])
            else:
                result.append(self._record[key])
        except (IndexError, KeyError):
            raise KeyError(f"Key or index '{key}' not found in the record.")

    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    result = {}
    if not keys:
        return dict(self._data)

    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self._data):
                raise IndexError(f"Index {key} is out of bounds")
            result[list(self._data.keys())[key]] = list(self._data.values())[key]
        elif isinstance(key, str):
            result[key] = self._data.get(key, None)
        else:
            raise TypeError(f"Key {key} must be an integer index or a string key")

    return result

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    if len(self.data) < 2:
        raise ValueError("Not enough data to pop a 16-bit integer")
    data = self.data[-2:]
    self.data = self.data[:-2]
    return int.from_bytes(data, byteorder='big', signed=False)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    if not isinstance(name, str) or not name.isidentifier():
        raise ValueError(f"Name must be a valid identifier: {name!r}")

    if not isinstance(fields, (list, tuple)):
        raise ValueError(f"Fields must be a list or tuple: {fields!r}")

    if not isinstance(srid_map, dict):
        raise ValueError(f"SRID map must be a dictionary: {srid_map!r}")

    # Validate field names
    seen = set()
    for field in fields:
        if not isinstance(field, str) or not field.isidentifier():
            raise ValueError(f"Field names must be valid identifiers: {field!r}")
        if field in seen:
            raise ValueError(f"Field name duplicated: {field!r}")
        seen.add(field)

    # Create the subclass
    class PointSubclass(Point):
        __slots__ = fields

        def __init__(self, *args, **kwargs):
            if len(args) > len(fields):
                raise TypeError(f"Expected {len(fields)} positional arguments, got {len(args)}")
            for i, arg in enumerate(args):
                setattr(self, fields[i], arg)
            for field, value in kwargs.items():
                if field not in fields:
                    raise TypeError(f"Unexpected keyword argument: {field!r}")
                setattr(self, field, value)
            for field in fields:
                if not hasattr(self, field):
                    raise TypeError(f"Missing value for field: {field!r}")

        def __repr__(self):
            field_values = ', '.join(f"{field}={getattr(self, field)!r}" for field in fields)
            return f"{name}({field_values})"

    PointSubclass.__name__ = name
    PointSubclass.srid_map = srid_map

    return PointSubclass

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    try:
        # Split the version string by dots and convert each part to an integer
        return tuple(int(part) for part in s.split('.'))
    except ValueError:
        # If conversion to integer fails, raise a ValueError with a descriptive message
        raise ValueError(f"Invalid version string: {s}. Expected format: major.minor.micro...")
    except AttributeError:
        # If the input is not a string, raise a TypeError
        raise TypeError(f"Expected a string, got {type(s).__name__}")

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if maxsize < 0:
        raise ValueError("maxsize must be a non-negative integer")

    def decorator(func):
        cache = {}
        order = []

        def wrapper(*args, **kwargs):
            key = (args, kwargs) if not typed else (args, tuple(sorted(kwargs.items())))
            if key in cache:
                order.remove(key)
                order.append(key)
                return cache[key]
            result = func(*args, **kwargs)
            if len(cache) >= maxsize:
                oldest_key = order.pop(0)
                del cache[oldest_key]
            cache[key] = result
            order.append(key)
            return result

        def clear():
            cache.clear()
            order.clear()

        wrapper.cache_clear = clear
        return functools.wraps(func)(wrapper)

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    from collections import defaultdict
    from functools import wraps

    def decorator(func):
        if maxsize is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        else:
            cache = {}
            frequency = defaultdict(int)
            key_order = []

            def wrapper(*args, **kwargs):
                if typed:
                    key = (args, tuple(sorted(kwargs.items())))
                else:
                    key = args + tuple(kwargs.values())

                if key in cache:
                    frequency[key] += 1
                    return cache[key]

                result = func(*args, **kwargs)
                if len(cache) >= maxsize:
                    # Find the least frequently used item
                    lfu_key = min(cache, key=lambda k: frequency[k])
                    del cache[lfu_key]
                    del frequency[lfu_key]
                    key_order.remove(lfu_key)

                cache[key] = result
                frequency[key] = 1
                key_order.append(key)
                return result

        return wraps(func)(wrapper)

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        # Assuming self is a dictionary or a similar data structure
        # that maintains insertion order (like collections.OrderedDict)
        key, value = next(iter(self.items()))
        del self[key]
        return key, value
    except StopIteration:
        raise KeyError('dictionary is empty')

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    try:
        if key not in self:
            self[key] = default
        return self[key]
    except Exception as e:
        logger.error(f"setdefault: An error occurred - {e}")
        return default

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    try:
        return self[key]
    except KeyError:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(method):
        if lock is None:
            def wrapper(self, *args, **kwargs):
                try:
                    c = cache(self)
                except Exception as e:
                    raise ValueError(f"Cache retrieval failed: {e}")
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except Exception as e:
                    raise ValueError(f"Cache storage failed: {e}")
                return v
        else:
            def wrapper(self, *args, **kwargs):
                try:
                    c = cache(self)
                except Exception as e:
                    raise ValueError(f"Cache retrieval failed: {e}")
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        c[k] = v
                except Exception as e:
                    raise ValueError(f"Cache storage failed: {e}")
                return v
        return _update_wrapper(wrapper, method)
    return decorator

@staticmethod
def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    if not isinstance(file_name, str) or not file_name:
        return False

    try:
        return os.path.isfile(file_name)
    except Exception:
        return False

