def directlyProvidedBy(object): # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    try:
        return object.__provides__
    except AttributeError:
        from zope.interface import providedBy
        return providedBy(object)

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not all(isinstance(cls, type) for cls in classes):
        raise TypeError("All elements in the classes list must be types.")

    minimal = []
    for cls in classes:
        if not any(issubclass(cls, c) for c in minimal):
            minimal.append(cls)
        else:
            minimal = [c for c in minimal if not issubclass(c, cls)]

    return minimal

def namesAndDescriptions(self, all=False): # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    try:
        if not hasattr(self, '_interface'):
            raise AttributeError("Interface not defined")

        attributes = self._interface.namesAndDescriptions(all=all)
        return attributes

    except AttributeError as e:
        print(f"Error: {e}")
        return {}
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return {}

def names(self, all=False): # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    try:
        if all:
            return list(self.__dict__.keys())
        else:
            return [attr for attr in self.__dict__ if not attr.startswith('_')]
    except AttributeError:
        return []

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if not isinstance(sequence, (tuple, list)):
        raise ValueError("Argument `sequence` must be a tuple or list")

    for item in sequence:
        if isinstance(item, tuple):
            _normalizeargs(item, output)
        elif hasattr(item, '__bases__') and (InterfaceClass in item.__bases__ or zope.interface.declarations.Implements in item.__bases__):
            output.append(item)
        else:
            raise ValueError("All items in `sequence` must be interfaces or implements specs")

    return output

