def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    self.context = {}
    if hasattr(self, 'initial_value'):
        self.bins = [self.initial_value for _ in self.bins]
    else:
        self.bins = self.make_bins()

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    try:
        coord = self._variables[coord_name]
    except KeyError:
        raise ValueError(f"Coordinate '{coord_name}' not found in variables.")

    try:
        err_indices = coord.attrs['err_indices']
    except KeyError:
        raise ValueError(f"Error indices not found for coordinate '{coord_name}'.")

    if not isinstance(err_indices, list):
        raise TypeError(f"Error indices for coordinate '{coord_name}' must be a list.")

    return err_indices

def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    if not isinstance(context, dict):
        raise ValueError("Context must be a dictionary")

    if 'error' not in context:
        context['error'] = {}

    # Assuming self.errors is a dictionary with error names as keys and indices as values
    for error_name, index in getattr(self, 'errors', {}).items():
        # Map error names to 'x', 'y', 'z' if they correspond to the first three coordinates
        if error_name == 'error_E_low':
            context['error']['x_low'] = {'index': index}
        elif error_name == 'error_E_mid':
            context['error']['y_low'] = {'index': index}
        elif error_name == 'error_E_high':
            context['error']['z_low'] = {'index': index}
        else:
            context['error'][error_name] = {'index': index}

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    if isinstance(seq, FillRequest) and not isinstance(seq, Source):
        return True
    if isinstance(seq, (list, tuple)):
        for item in seq:
            if isinstance(item, FillRequest) and not isinstance(item, Source):
                return True
    return False

