def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if not app or not hasattr(app, 'spec') or not hasattr(app.spec, 'manifest'):
        raise ValueError("Invalid application object or missing manifest")

    default_schema = {}
    for resource in app.spec.manifest:
        if not isinstance(resource, dict) or 'kind' not in resource:
            continue

        kind = resource['kind']
        if kind not in app.spec.observer_schema:
            default_schema[kind] = {
                "metrics": [
                    {"name": "cpu_usage", "type": "resource"},
                    {"name": "memory_usage", "type": "resource"}
                ]
            }

    return default_schema

