def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not isinstance(manifest_files, list) or not isinstance(digests_used, list):
        raise ValueError("Both manifest_files and digests_used must be lists.")

    # Extract digests from manifest_files
    digests_in_manifest = set()
    for file in manifest_files:
        if not isinstance(file, dict) or 'digest' not in file:
            raise ValueError("Each file in manifest_files must be a dictionary containing a 'digest' key.")
        digests_in_manifest.add(file['digest'])

    # Check if all digests in manifest are present in digests_used
    for digest in digests_in_manifest:
        if digest not in digests_used:
            raise ValueError(f"Digest {digest} present in manifest but not used.")

    # Check if all used digests are present in manifest
    for digest in digests_used:
        if digest not in digests_in_manifest:
            raise ValueError(f"Digest {digest} used but not present in manifest.")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise TypeError("The prior must be an instance of InventoryValidator")

    if self.inventory.keys() != prior.inventory.keys():
        raise ValueError("The prior inventory must have the same items as the current inventory")

    for item, current_value in self.inventory.items():
        prior_value = prior.inventory[item]
        if not isinstance(current_value, (int, float)) or not isinstance(prior_value, (int, float)):
            raise ValueError(f"Inventory values for {item} must be numbers")
        if current_value < prior_value:
            raise ValueError(f"The current inventory value for {item} cannot be less than the prior inventory value")

    if self.timestamp <= prior.timestamp:
        raise ValueError("The current inventory timestamp must be after the prior inventory timestamp")

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary.")
    if not isinstance(version, str):
        raise ValueError("Version must be a string.")

    logical_path_map = {}

    try:
        version_data = inventory[version]
    except KeyError:
        raise ValueError(f"Version {version} not found in inventory.")

    if not isinstance(version_data, dict):
        raise ValueError(f"Data for version {version} must be a dictionary.")

    for logical_path, content_files in version_data.items():
        if not isinstance(content_files, list):
            raise ValueError(f"Content files for {logical_path} must be a list.")
        logical_path_map[logical_path] = set(content_files)

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if not isinstance(manifest_files, list):
        raise ValueError("Manifest files must be a list")

    for file_name, file_fixity in fixity.items():
        if file_name not in manifest_files:
            raise ValueError(f"File '{file_name}' in fixity block is not listed in the manifest")

        if not isinstance(file_fixity, dict):
            raise ValueError(f"Fixity information for '{file_name}' must be a dictionary")

        if 'algorithm' not in file_fixity or 'value' not in file_fixity:
            raise ValueError(f"Fixity information for '{file_name}' must include 'algorithm' and 'value' keys")

        if not isinstance(file_fixity['algorithm'], str) or not isinstance(file_fixity['value'], str):
            raise ValueError(f"Algorithm and value for '{file_name}' must be strings")

