        raise ValueError("The arg parameter must be a string.")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = set([cls])

    while queue:
        c = queue.pop()
        seen.add(c)

        sc = c.__subclasses__()
        for c in sc:
            if c not in seen:
                queue.add(c)

    seen.remove(cls)
    return seen

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty.")
    if not string:
        raise ValueError("String cannot be empty.")

    base = len(alphabet)
    inverse_alphabet = {char: index for index, char in enumerate(alphabet)}

    number = 0
    for char in string:
        if char not in inverse_alphabet:
            raise ValueError(f"Character '{char}' not found in the alphabet.")
        number = number * base + inverse_alphabet[char]

    return number

def unquote(name):
    """Remove quotes from the given name."""
