def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import toml
    import os

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        if not os.path.exists(filename):
            log_record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f"Configuration file not found: {filename}",
                args=(),
                exc_info=None
            )
            log_records.append(log_record)
            continue

        try:
            with open(filename, 'r') as file:
                config = toml.load(file)
                config_dict[filename] = config
        except Exception as e:
            log_record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f"Error parsing configuration file {filename}: {str(e)}",
                args=(),
                exc_info=e
            )
            log_records.append(log_record)

    if overrides:
        for key, value in overrides.items():
            for config in config_dict.values():
                config[key] = value

    if resolve_env:
        import re
        env_var_pattern = re.compile(r'\$\{([^}]+)\}')
        for filename, config in config_dict.items():
            try:
                config_dict[filename] = _resolve_env_vars(config, env_var_pattern)
            except Exception as e:
                log_record = logging.LogRecord(
                    name='config_loader',
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f"Error resolving environment variables in configuration file {filename}: {str(e)}",
                    args=(),
                    exc_info=e
                )
                log_records.append(log_record)

    return config_dict, log_records

def _resolve_env_vars(config, pattern):
    if isinstance(config, dict):
        return {k: _resolve_env_vars(v, pattern) for k, v in config.items()}
    elif isinstance(config, list):
        return [_resolve_env_vars(v, pattern) for v in config]
    elif isinstance(config, str):
        match = pattern.search(config)
        if match:
            env_var = match.group(1)
            env_value = os.getenv(env_var)
            if env_value is not None:
                config = pattern.sub(env_value, config, count=1)
                return _resolve_env_vars(config, pattern)
        return config
    return config

