def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not hasattr(iface, '__implements__'):
        raise ValueError("iface must be an interface with an __implements__ attribute")

    if not isinstance(candidate, type):
        raise ValueError("candidate must be a class")

    missing_methods = [method for method in iface.__implements__ if not hasattr(candidate, method)]

    if missing_methods:
        if tentative:
            return False
        else:
            raise NotImplementedError(f"candidate does not implement methods: {missing_methods}")

    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    metaclasses = set()
    for base in bases:
        try:
            metaclass = type(base)
            if metaclass not in metaclasses:
                metaclasses.add(metaclass)
        except Exception:
            continue

    if not metaclasses:
        return type

    if len(metaclasses) == 1:
        return metaclasses.pop()

    # If there are multiple metaclasses, find a common base metaclass
    common_base = None
    for m in metaclasses:
        if common_base is None:
            common_base = m
        else:
            common_base = type.__common__(common_base, m)
            if common_base is None:
                raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of all its bases' metaclasses")

    return common_base

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key in self:
        value = self[key]
        del self[key]
        return value
    elif default is not __marker:
        return default
    else:
        raise KeyError(key)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError('dictionary is empty')
    min_freq = min(self._freq.values())
    for key in self._order:
        if self._freq[key] == min_freq:
            value = self[key]
            del self[key]
            return key, value
    raise KeyError('dictionary is empty')

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    if not self:
        raise KeyError('dictionary is empty')
    key = next(reversed(self))
    value = self.pop(key)
    return (key, value)

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    import random
    if not self:
        raise KeyError('dictionary is empty')
    key = random.choice(list(self.keys()))
    value = self.pop(key)
    return (key, value)

