def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Legacy payload check
    try:
        legacy_data = json.loads(decode_if_bytes(request.body))
        if "diaspora_handle" in legacy_data:
            return True
    except Exception:
        pass
    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # Check for common Matrix request headers or parameters
        if 'User-Agent' in request.headers and 'Matrix' in request.headers['User-Agent']:
            return True
        if 'Authorization' in request.headers and request.headers['Authorization'].startswith('Bearer '):
            return True
        if 'Content-Type' in request.headers and request.headers['Content-Type'] == 'application/json':
            return True
        # Check for common Matrix request paths
        if request.path.startswith('/_matrix/'):
            return True
    except AttributeError:
        # If request object does not have expected attributes, it's not a Matrix request
        return False
    return False

