    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if not url:
        raise ValueError("URL is required")

    if not url.startswith(('http://', 'https://')):
        raise ValueError("URL must include protocol (http or https)")

    if document_path and not document_path.startswith('/'):
        raise ValueError("document_path must be an absolute path starting with '/'")

    default_document_path = '/.well-known/nodeinfo'
    nodeinfo_path = document_path if document_path else default_document_path

    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": f"{url}{nodeinfo_path}?schema=1.0"
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree as ET

    try:
        # Try to parse as JSON
        data = json.loads(document)
        if "links" in data:
            return {
                link["rel"]: link["href"]
                for link in data["links"]
            }
    except json.JSONDecodeError:
        # If JSON parsing fails, try to parse as XRD
        try:
            root = ET.fromstring(document)
            return {
                link.attrib["rel"]: link.attrib["href"]
                for link in root.findall(".//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link")
            }
        except ET.ParseError:
            # If both parsing attempts fail, log the error and return an empty dictionary
            logger.warning("parse_diaspora_webfinger: failed to parse document as JSON or XRD")
            return {}

    # If the document is neither valid JSON nor XRD, return an empty dictionary
    return {}

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        if "@" not in handle:
            return None
        host = handle.split("@")[1]
        url = f"https://{host}/.well-known/webfinger?resource=acct:{handle}"
        with closing(urllib.request.urlopen(url)) as response:
            if response.getcode() == 200:
                return response.read().decode('utf-8')
    except Exception:
        pass
    return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except (AttributeError, IndexError):
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if exception:
        logger.warning("retrieve_and_parse_diaspora_webfinger: failed to fetch document for handle %s: %s", handle, exception)
        return None
    if document:
        try:
            return parse_diaspora_webfinger(document)
        except Exception as e:
            logger.warning("retrieve_and_parse_diaspora_webfinger: failed to parse document for handle %s: %s", handle, e)
            return None
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        logger.warning("retrieve_and_parse_diaspora_webfinger: failed to retrieve host-meta for handle %s", handle)
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        logger.warning("retrieve_and_parse_diaspora_webfinger: failed to fetch document from lrdd URL for handle %s: %s", handle, exception)
        return None
    if document:
        try:
            return parse_diaspora_webfinger(document)
        except Exception as e:
            logger.warning("retrieve_and_parse_diaspora_webfinger: failed to parse document from lrdd URL for handle %s: %s", handle, e)
            return None
    return None

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    if not isinstance(host, str) or not host:
        logger.warning("retrieve_diaspora_host_meta: invalid host given: %s", host)
        return None

    try:
        document, code, exception = fetch_document(host=host, path="/.well-known/host-meta")
    except Exception as e:
        logger.error("retrieve_diaspora_host_meta: error fetching document from %s: %s", host, e)
        return None

    if exception:
        logger.error("retrieve_diaspora_host_meta: exception occurred while fetching document from %s: %s", host, exception)
        return None

    if not document:
        logger.warning("retrieve_diaspora_host_meta: no document retrieved from %s", host)
        return None

    try:
        xrd = XRD.parse_xrd(document)
    except Exception as e:
        logger.error("retrieve_diaspora_host_meta: error parsing XRD document from %s: %s", host, e)
        return None

    return xrd

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        file_names = []
        for directory in settings_dirs:
            if os.path.isdir(directory):
                for fname in os.listdir(directory):
                    if fname.endswith(spec_option):
                        file_names.append(os.path.join(directory, fname))
        return sorted(file_names)
    except (TypeError, OSError):
        return []

@classmethod
def ansible_config_manager(cls):
    """Gets the ansible config manager. """
    try:
        from ansible.config.manager import ConfigManager
        return ConfigManager()
    except ImportError as e:
        raise RuntimeError("Ansible is not installed or the ConfigManager class could not be imported.") from e
    except Exception as e:
        raise RuntimeError(f"An error occurred while getting the ansible config manager: {e}") from e

@classmethod
def workspace_manager(cls):
    """Gets the workspace manager. """
    try:
        return cls._workspace_manager
    except AttributeError:
        raise RuntimeError("Workspace manager is not initialized.")

def plugins_manager(cls):
    """Gets the plugin manager. """
    if not hasattr(cls, '_plugin_manager'):
        cls._plugin_manager = PluginManager()
    return cls._plugin_manager

@classmethod
def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    import yaml

    if spec_content is None:
        raise IRValidatorException("spec_content argument must be supplied")

    try:
        spec_data = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML content: {e}")

    required_fields = {'name', 'version', 'description'}  # Example required fields
    missing_fields = required_fields - spec_data.keys()

    if missing_fields:
        raise IRValidatorException(f"Mandatory fields missing in spec file: {', '.join(missing_fields)}")

    return spec_data

@classmethod
def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise ValueError("yaml_file argument must be supplied")

    try:
        with open(yaml_file, 'r') as f:
            data = yaml.load(f, Loader=yaml.FullLoader)
    except Exception as e:
        raise IRValidatorException(f"There was a problem parsing the file: {e}")

    required_fields = {'name', 'version', 'description'}  # Example required fields
    missing_fields = required_fields - set(data.keys())

    if missing_fields:
        raise IRValidatorException(f"Mandatory data is missing in file: {missing_fields}")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if not isinstance(parser_dict, dict):
        raise ValueError("parser_dict must be a dictionary")

    if 'include' not in parser_dict:
        return parser_dict

    include_directive = parser_dict.pop('include')
    if not isinstance(include_directive, dict):
        raise ValueError("include directive must be a dictionary")

    for key, value in include_directive.items():
        if key in parser_dict:
            if isinstance(parser_dict[key], dict) and isinstance(value, dict):
                parser_dict[key].update(value)
            else:
                parser_dict[key] = value
        else:
            parser_dict[key] = value

    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    try:
        defaults = {}
        for key, value in self.spec.items():
            if isinstance(value, dict) and 'default' in value:
                defaults[key] = value['default']
            elif not isinstance(value, dict):
                defaults[key] = value
        return defaults
    except AttributeError:
        raise ValueError("The spec attribute is not properly set or is not a dictionary.")
    except Exception as e:
        raise RuntimeError(f"An error occurred while resolving spec defaults: {e}")

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    return getattr(self, '_deprecated_args', {})

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    if not isinstance(cli_args, dict) or not isinstance(answer_file_args, dict):
        raise ValueError("Both cli_args and answer_file_args must be dictionaries.")

    deprecated_args = {
        'old_arg1': 'new_arg1',
        'old_arg2': 'new_arg2',
        # Add more deprecated arguments as needed
    }

    all_args = {**cli_args, **answer_file_args}

    for old_arg, new_arg in deprecated_args.items():
        if old_arg in all_args:
            print(f"Warning: The argument '{old_arg}' has been deprecated in favor of '{new_arg}'.")
            if new_arg not in all_args:
                print(f"Please use '{new_arg}' instead.")
            else:
                print(f"Both '{old_arg}' and '{new_arg}' are provided. '{old_arg}' will be ignored in favor of '{new_arg}'.")

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    try:
        if not isinstance(command_name, str):
            raise ValueError("command_name must be a string")

        # Assuming self.command_options is a dictionary mapping command names to their options
        if command_name in self.command_options:
            return self.command_options[command_name]
        else:
            raise KeyError(f"No options found for command: {command_name}")

    except Exception as e:
        print(f"An error occurred: {e}")
        return []

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    try:
        command = self.commands[command_name]
        return command['options'][argument_name]
    except (KeyError, TypeError):
        return None

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    silenced_args = []
    try:
        for arg, value in vars(args).items():
            if value is None or value == False:
                silenced_args.append(arg)
    except Exception as e:
        print(f"An error occurred: {e}")
    return silenced_args

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    if not hasattr(self, 'required_args'):
        raise AttributeError("Class does not define 'required_args' attribute.")

    if not isinstance(args, dict):
        raise TypeError("Arguments must be provided as a dictionary.")

    missing_args = [arg for arg in self.required_args if arg not in args or args[arg] is None]

    if missing_args:
        raise ValueError(f"Missing required arguments: {', '.join(missing_args)}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not isinstance(options_spec, list):
        raise TypeError("options_spec must be a list")
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")

    matched_args = []
    for option in options_spec:
        if 'required_when' in option:
            condition = option['required_when']
            if isinstance(condition, str):
                condition = {condition}
            elif not isinstance(condition, set):
                raise ValueError("required_when must be a string or a set of strings")

            if condition.issubset(args):
                matched_args.append(option.get('name', ''))

    return matched_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise ValueError("args must be a dictionary")

    for arg_name, arg_value in args.items():
        if not isinstance(arg_value, dict):
            raise ValueError(f"Argument '{arg_name}' must be a dictionary containing 'value' and 'length' keys")

        value = arg_value.get('value')
        length = arg_value.get('length')

        if value is None:
            raise ValueError(f"Argument '{arg_name}' is missing 'value' key")
        if length is None:
            raise ValueError(f"Argument '{arg_name}' is missing 'length' key")
        if not isinstance(length, int):
            raise ValueError(f"Length for argument '{arg_name}' must be an integer")
        if length < 0:
            raise ValueError(f"Length for argument '{arg_name}' must be non-negative")

        if isinstance(value, str) and len(value) > length:
            raise ValueError(f"Value for argument '{arg_name}' is longer than specified length of {length}")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise ValueError("Arguments must be provided as a dictionary.")

    for arg_name, arg_value in args.items():
        if hasattr(self, 'choices') and arg_name in self.choices:
            available_choices = self.choices[arg_name]
            if arg_value not in available_choices:
                raise ValueError(f"Invalid value for '{arg_name}': {arg_value}. Must be one of {available_choices}.")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("Arguments must be provided as a dictionary with 'value', 'min', and 'max' keys.")

    value = args.get('value')
    min_value = args.get('min')
    max_value = args.get('max')

    if value is None:
        raise ValueError("Missing 'value' in arguments.")
    if min_value is None:
        raise ValueError("Missing 'min' in arguments.")
    if max_value is None:
        raise ValueError("Missing 'max' in arguments.")

    if not isinstance(value, (int, float)):
        raise TypeError("The 'value' must be an integer or float.")
    if not isinstance(min_value, (int, float)):
        raise TypeError("The 'min' must be an integer or float.")
    if not isinstance(max_value, (int, float)):
        raise TypeError("The 'max' must be an integer or float.")

    if min_value > max_value:
        raise ValueError("The 'min' value must be less than or equal to the 'max' value.")

    if not (min_value <= value <= max_value):
        raise ValueError(f"The 'value' {value} is not between 'min' {min_value} and 'max' {max_value}.")

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    if not isinstance(args, dict):
        raise ValueError("args must be a dictionary")

    for key, value in args.items():
        if key.startswith('control_'):
            control_args[key] = value
        elif key.startswith('custom_'):
            custom_args[key] = value
        else:
            nested_args[key] = value

    # If custom arguments are present, they override nested arguments
    nested_args.update(custom_args)

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")

    if extra_vars is None:
        return vars_dict

    if not isinstance(extra_vars, list):
        raise ValueError("extra_vars must be a list")

    for item in extra_vars:
        if not isinstance(item, dict):
            raise ValueError("Each item in extra_vars must be a dictionary")
        vars_dict.update(item)

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import logging

    logger = logging.getLogger(__name__)

    if not playbook_path:
        raise ValueError("playbook_path must be provided")

    command = ["ansible-playbook"]

    if verbose:
        command.append('-' + 'v' * verbose)

    if extra_vars:
        extra_vars_str = ' '.join([f"{k}={v}" for k, v in extra_vars.items()])
        command.extend(['--extra-vars', extra_vars_str])

    if ansible_args:
        for arg, value in ansible_args.items():
            if value is None:
                command.append(f"--{arg}")
            else:
                command.extend([f"--{arg}", str(value)])

    command.append(playbook_path)

    logger.debug("Executing Ansible call `%s`", " ".join(command))
    try:
        p = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr = p.communicate()
        if p.returncode != 0:
            raise RuntimeError(f"Ansible reported an error when executing playbook {playbook_path}: {stderr.decode()}")
        return stdout.decode()
    except Exception as e:
        logger.error(f"An error occurred while running ansible-playbook: {e}")
        raise

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(values_dict, dict):
        raise ValueError("values_dict must be a dictionary")

    try:
        parser = self.parsers[parser_name]
    except KeyError:
        raise ValueError(f"No parser found for command: {parser_name}")

    for arg, value in values_dict.items():
        try:
            action = next(action for action in parser._actions if action.dest == arg)
        except StopIteration:
            continue  # Skip arguments not found in the parser

        if action.type is not None:
            try:
                values_dict[arg] = action.type(value)
            except (ValueError, TypeError) as e:
                raise ValueError(f"Error converting argument '{arg}': {e}")

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def flatten_dict(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    try:
        spec_path = os.path.join(plugin_dir, 'plugin_spec.json')
        with open(spec_path, 'r') as file:
            plugin_spec = json.load(file)
        return flatten_dict(plugin_spec)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        raise ValueError(f"Error reading or parsing plugin spec file: {e}")
    except Exception as e:
        raise Exception(f"An unexpected error occurred: {e}")

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if 'CONFIG_PATH' not in os.environ:
        try:
            default_config_path = self.get_default_config_path()
            os.environ['CONFIG_PATH'] = default_config_path
        except Exception as e:
            raise RuntimeError(f"Failed to set default config path: {e}")

def get_default_config_path(self):
    # This method should be implemented to return the default config path
    # For the purpose of this example, let's assume it returns a hardcoded path
    return '/path/to/default/config'

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    stripped_path = path[len(root):]
    # Remove any leading slash that may result from stripping
    if stripped_path.startswith(os.sep):
        stripped_path = stripped_path[len(os.sep):]
    return stripped_path
